using System.Collections.Generic;
using UnityEngine;

namespace KingLastPiece
{
    /// <summary>
    /// The black aura of an empowered piece: the AC Little Enchant Mesh VFX "Dark Lvl 1–3" prefab, emitting from the
    /// piece's own silhouette and recolored black. The pack's particles are additive (black would vanish), so their
    /// materials are swapped for alpha-blended URP copies (generated by KING ▸ Setup ▸ Endless Assets).
    /// </summary>
    public static class EliteAura
    {
        static readonly Color Ink = new Color(0.02f, 0.02f, 0.025f);
        static readonly Dictionary<PieceType, Mesh> silhouettes = new Dictionary<PieceType, Mesh>();

        /// <summary>
        /// Wraps <paramref name="model"/> in the tier's aura (null when the pack isn't there). Two tiers: Dark I wears the
        /// pack's "Dark Lvl 1" at 0.6× size, Dark II its "Dark Lvl 3" at full size.
        /// </summary>
        public static GameObject Attach(Transform model, PieceType type, int tier)
        {
            var lib = FxLibrary.Instance;
            if (lib == null || lib.eliteAura == null || tier < 1 || lib.eliteAura.Length == 0) return null;
            int index = Mathf.Min(tier >= 2 ? 2 : 0, lib.eliteAura.Length - 1);
            float size = tier >= 2 ? 1f : 0.6f;
            var prefab = lib.eliteAura[index];
            if (prefab == null) return null;

            Mesh mesh = Silhouette(model, type);
            var fx = Object.Instantiate(prefab, model);
            fx.name = $"Dark Aura {tier}";
            fx.transform.localPosition = Vector3.zero;
            fx.transform.localRotation = Quaternion.identity;
            fx.transform.localScale = Vector3.one;
            foreach (var ps in fx.GetComponentsInChildren<ParticleSystem>(true))
            {
                var main = ps.main;
                main.simulationSpace = ParticleSystemSimulationSpace.Local;   // hugs the piece (no smoke trail left behind as it moves)
                main.scalingMode = ParticleSystemScalingMode.Hierarchy;
                // Black on a black piece barely shows: denser, darker smoke that rises off the piece like dark fire, so it
                // reads against the squares and the hall around it. The pack's big glow/smoke puffs are trimmed a little.
                if (main.startSizeMultiplier >= 1f) main.startSizeMultiplier *= 0.8f;
                main.startSizeMultiplier *= size;
                float a = main.startColor.mode == ParticleSystemGradientMode.Color ? main.startColor.color.a : 1f;
                main.startColor = new ParticleSystem.MinMaxGradient(new Color(Ink.r, Ink.g, Ink.b, Mathf.Min(0.92f, a * 4f)));
                var emission = ps.emission;
                emission.rateOverTimeMultiplier *= 2f;
                var rise = ps.velocityOverLifetime;
                rise.enabled = true;
                rise.space = ParticleSystemSimulationSpace.Local;
                rise.x = new ParticleSystem.MinMaxCurve(0f, 0f);   // all three axes must use the same curve mode
                rise.y = new ParticleSystem.MinMaxCurve(0.35f * size, 0.9f * size);
                rise.z = new ParticleSystem.MinMaxCurve(0f, 0f);
                var col = ps.colorOverLifetime;
                if (col.enabled)
                {
                    // Keep the fades, drop the hues (the start color makes it black).
                    var src = col.color.mode == ParticleSystemGradientMode.TwoGradients ? col.color.gradientMax : col.color.gradient;
                    if (src != null)
                    {
                        var g = new Gradient();
                        g.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) }, src.alphaKeys);
                        col.color = new ParticleSystem.MinMaxGradient(g);
                    }
                }
                var shape = ps.shape;
                if (mesh != null && (shape.shapeType == ParticleSystemShapeType.MeshRenderer || shape.shapeType == ParticleSystemShapeType.Mesh ||
                                     shape.shapeType == ParticleSystemShapeType.SkinnedMeshRenderer))
                {
                    shape.shapeType = ParticleSystemShapeType.Mesh;
                    shape.mesh = mesh;
                    shape.position = Vector3.zero;
                    shape.rotation = Vector3.zero;
                    shape.scale = Vector3.one;
                }
                var r = ps.GetComponent<ParticleSystemRenderer>();
                if (r != null) r.sharedMaterials = Swap(lib, r.sharedMaterials);
            }
            foreach (var a in fx.GetComponentsInChildren<AudioSource>()) a.enabled = false;
            return fx;
        }

        static readonly int BaseColorId = Shader.PropertyToID("_BaseColor");
        static MaterialPropertyBlock mpb;

        /// <summary>Fades the aura (0 = gone, 1 = full) without touching the shared materials.</summary>
        public static void SetOpacity(GameObject aura, float opacity)
        {
            if (aura == null) return;
            mpb ??= new MaterialPropertyBlock();
            foreach (var r in aura.GetComponentsInChildren<ParticleSystemRenderer>())
            {
                r.GetPropertyBlock(mpb);
                mpb.SetColor(BaseColorId, new Color(0.03f, 0.03f, 0.035f, opacity));
                r.SetPropertyBlock(mpb);
            }
        }

        static Material[] Swap(FxLibrary lib, Material[] mats) => Swap(mats, lib.eliteAuraSource, lib.eliteAuraBlack);

        static Material[] Swap(Material[] mats, Material[] sources, Material[] blacks)
        {
            if (sources == null || blacks == null) return mats;
            for (int i = 0; i < mats.Length; i++)
            {
                int k = System.Array.IndexOf(sources, mats[i]);
                if (k >= 0 && k < blacks.Length && blacks[k] != null) mats[i] = blacks[k];
            }
            return mats;
        }

        /// <summary>
        /// Turns an effect black (e.g. the Dizzy swirl): black start colour (alpha × <paramref name="alphaBoost"/>), fades
        /// kept but hues dropped, and its additive materials swapped for alpha-blended black copies (black would vanish
        /// in additive). Trails too.
        /// </summary>
        public static void Blacken(GameObject fx, Material[] sources, Material[] blacks, float alphaBoost = 1f)
        {
            if (fx == null) return;
            foreach (var ps in fx.GetComponentsInChildren<ParticleSystem>(true))
            {
                var main = ps.main;
                float a = main.startColor.mode == ParticleSystemGradientMode.Color ? main.startColor.color.a : 1f;
                main.startColor = new ParticleSystem.MinMaxGradient(new Color(Ink.r, Ink.g, Ink.b, Mathf.Min(0.95f, a * alphaBoost)));
                var col = ps.colorOverLifetime;
                if (col.enabled)
                {
                    var src = col.color.mode == ParticleSystemGradientMode.TwoGradients ? col.color.gradientMax : col.color.gradient;
                    if (src != null)
                    {
                        var g = new Gradient();
                        g.SetKeys(new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) }, src.alphaKeys);
                        col.color = new ParticleSystem.MinMaxGradient(g);
                    }
                }
                var trails = ps.trails;
                if (trails.enabled)
                {
                    trails.inheritParticleColor = true;
                    trails.colorOverLifetime = new ParticleSystem.MinMaxGradient(Color.white);
                }
                var r = ps.GetComponent<ParticleSystemRenderer>();
                if (r == null) continue;
                r.sharedMaterials = Swap(r.sharedMaterials, sources, blacks);
                if (r.trailMaterial != null)
                {
                    var t = Swap(new[] { r.trailMaterial }, sources, blacks);
                    r.trailMaterial = t[0];
                }
            }
            // Trail renderers (the swirl's ribbons): black copies of their materials, black along the whole trail.
            foreach (var tr in fx.GetComponentsInChildren<TrailRenderer>(true))
            {
                tr.sharedMaterials = Swap(tr.sharedMaterials, sources, blacks);
                var g = tr.colorGradient;
                var alphas = g.alphaKeys;
                for (int i = 0; i < alphas.Length; i++) alphas[i].alpha = Mathf.Min(0.95f, alphas[i].alpha * alphaBoost);
                var ng = new Gradient();
                ng.SetKeys(new[] { new GradientColorKey(Ink, 0f), new GradientColorKey(Ink, 1f) }, alphas);
                tr.colorGradient = ng;
            }
        }

        /// <summary>The model's parts merged into one mesh in its own space (cached per piece type), for the aura to emit from.</summary>
        static Mesh Silhouette(Transform model, PieceType type)
        {
            if (silhouettes.TryGetValue(type, out var cached) && cached != null) return cached;
            var parts = new List<CombineInstance>();
            Matrix4x4 toModel = model.worldToLocalMatrix;
            foreach (var mf in model.GetComponentsInChildren<MeshFilter>())
            {
                var m = mf.sharedMesh;
                if (m == null || !m.isReadable) continue;
                parts.Add(new CombineInstance { mesh = m, transform = toModel * mf.transform.localToWorldMatrix });
            }
            if (parts.Count == 0) return null;
            var mesh = new Mesh { name = model.name + " Silhouette" };
            mesh.CombineMeshes(parts.ToArray(), true, true);
            silhouettes[type] = mesh;
            return mesh;
        }
    }
}
